-- =========================================================================
-- Phlo AI Ops - company directory seed (138 people, per HR employee list 2026-07-17)
-- Run AFTER people_directory_migration.sql.
-- Idempotent - re-running updates display_name/title/team/start_date for
-- any rows whose canonical email already exists.
-- =========================================================================

on conflict (email) do update set
  display_name = excluded.display_name,
  title        = excluded.title,
  team         = excluded.team,
  start_date   = excluded.start_date,
  updated_at   = now();
